export const bytesOf = (base64: string) =>
  Uint8Array.from(atob(base64), (char) => char.charCodeAt(0));

export const SVG = new TextEncoder().encode(
  '<?xml version="1.0"?>\n<svg xmlns="http://www.w3.org/2000/svg" width="10" height="20"></svg>',
);

// the start of an EMF: record type 1, " EMF" signature at offset 40
export const EMF = (() => {
  const bytes = new Uint8Array(88);
  bytes.set([1, 0, 0, 0], 0);
  bytes.set([0x20, 0x45, 0x4d, 0x46], 40);
  return bytes;
})();

export const WMF = new Uint8Array([0xd7, 0xcd, 0xc6, 0x9a, 0, 0, 0, 0]);

export const dataUrl = (mime: string, base64: string) =>
  `data:${mime};base64,${base64}`;
